-- Physical Science final module. Run seed_psc_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'physical-science';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Physical Science Investigation Report$j$, $j${"prompt": "Complete a safe investigation and write a report of at least 600 words. Ask a parent, guardian or teacher for permission and supervision before you begin. Use only everyday household items. Do not use open flames, unknown chemicals, household electrical outlets or anything that could cause harm. If you choose a circuit, use only a small battery of 9 volts or less. Choose one question: (a) Which household objects float or sink, and what are their densities? (b) How does the container affect how fast hot water cools? (c) How does the height of a ramp change the speed or acceleration of a toy car? (d) How do series and parallel arrangements change the brightness of small bulbs on a low voltage battery? Write complete sentences, show every calculation and label each part. Proverbs 25:2 says, It is the glory of God to conceal a thing: but the honour of kings is to search out a matter.\n\nPart 1: The Question and Hypothesis. State your question and your hypothesis, and explain the science that led to your prediction.\nPart 2: Plan and Safety. List your materials, your independent variable, dependent variable and at least three controls. List the safety rules you followed and how an adult supervised.\nPart 3: Procedure. Describe your steps clearly enough that another student could repeat them.\nPart 4: Data. Present at least 5 trials or measurements in a table with units, and make a graph or chart.\nPart 5: Calculations. Show at least three calculations with units, such as density, speed, acceleration, work, power, energy, heat or current, and apply the correct formula to each.\nPart 6: Analysis. Tell what your data show, name the physical science principles involved (such as density, Newton's laws, energy conservation, heat transfer or Ohm's law), and compare your result with your hypothesis.\nPart 7: Sources of Error. Describe at least three sources of error and how you could improve the test.\nPart 8: Faith and Application. Explain how Psalm 111:2 and Proverbs 11:1 guide honest, careful science, and describe how you could use physical science in a future calling.", "rubric": "100 points. Part 1, question and hypothesis: 10 points. Part 2, plan and safety: 15 points. Part 3, procedure: 10 points. Part 4, data: 15 points. Part 5, calculations: 15 points. Part 6, analysis: 15 points. Part 7, sources of error: 5 points. Part 8, faith and application: 10 points. Grammar, conventions and respectful tone: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Physical Science Investigation Report$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Physical Science$j$, $j${"questions": [{"q": "In a fair test, the variable you deliberately change is the:", "options": ["Dependent variable", "Independent variable", "Control", "Conclusion"]}, {"q": "A sample has a mass of 60 g and a volume of 20 cubic centimeters. Its density is:", "options": ["80 g per cubic centimeter", "0.33 g per cubic centimeter", "3 g per cubic centimeter", "40 g per cubic centimeter"]}, {"q": "A gas changing directly into a solid, as frost forms, is called:", "options": ["Condensation", "Melting", "Sublimation", "Deposition"]}, {"q": "An atom has 8 protons and 8 neutrons. Its mass number is:", "options": ["16", "0", "8", "24"]}, {"q": "Elements in the same group of the periodic table have the same number of:", "options": ["Energy levels", "Total electrons", "Neutrons", "Valence electrons"]}, {"q": "Which pair of elements forms an ionic bond?", "options": ["Sodium and chlorine", "Nitrogen and nitrogen", "Carbon and oxygen", "Hydrogen and oxygen"]}, {"q": "In the balanced equation 2H2 + O2 yields 2H2O, how many hydrogen atoms are on each side?", "options": ["4", "1", "2", "6"]}, {"q": "A solution with a pH of 10 is:", "options": ["Impossible to classify", "Neutral", "Acidic", "Basic"]}, {"q": "A car travels 120 km in 2 hours. Its average speed is:", "options": ["240 km/h", "60 km/h", "122 km/h", "0.017 km/h"]}, {"q": "A 5 kg object accelerates at 2 m/s squared. The net force is:", "options": ["2.5 N", "10 N", "7 N", "0.4 N"]}, {"q": "A 2 kg object moves at 4 m/s. Its kinetic energy is:", "options": ["32 J", "4 J", "8 J", "16 J"]}, {"q": "A lever, a pulley and an inclined plane are all examples of:", "options": ["Compounds", "Waves", "Simple machines", "Circuits"]}, {"q": "Heat transferred through empty space by waves is:", "options": ["Radiation", "Conduction", "Condensation", "Convection"]}, {"q": "A wave has a frequency of 10 Hz and a wavelength of 3 m. Its speed is:", "options": ["30 m/s", "3.3 m/s", "7 m/s", "13 m/s"]}, {"q": "A 12 volt battery drives current through a 6 ohm resistor. The current is:", "options": ["0.5 A", "2 A", "72 A", "18 A"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Physical Science$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,3,0,3,0,0,3,1,1,3,2,0,0,1}'::int[], array[$j$The independent variable is the one you change.$j$,$j$60 divided by 20 equals 3.$j$,$j$Gas to solid is deposition.$j$,$j$8 plus 8 equals 16.$j$,$j$Valence electrons give similar chemical behavior.$j$,$j$A metal gives an electron to a nonmetal.$j$,$j$2 times 2 equals 4 on each side.$j$,$j$A pH above 7 is basic.$j$,$j$120 divided by 2 equals 60.$j$,$j$Force equals 5 times 2.$j$,$j$One half times 2 times 16 equals 16.$j$,$j$These are three of the six simple machines.$j$,$j$Radiation does not need a medium.$j$,$j$Speed equals 10 times 3.$j$,$j$12 divided by 6 equals 2.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Physical Science$j$ on conflict (item_id) do nothing;
end
$seed$;
